#include <iostream>
using namespace std;
class Space {
    int x, y, z;
public:
    Space(int a, int b, int c) : x(a), y(b), z(c) {}
    void operator - () { // Overloading unary minus
        x = -x;
        y = -y;
        z = -z;
    }
    void display() {
        cout << "x=" << x << ", y=" << y << ", z=" << z << endl;
    }
};
int main() {
    Space s(10, -20, 30);
    cout << "Original: "; s.display();
    -s; // Calls operator-
    cout << "After unary minus: "; s.display();
    return 0;
}

