நிரல்:
class Space {
    int x, y, z;
public:
    Space(int a, int b, int c): x(a), y(b), z(c) {}
    void operator - () {
        x = -x; y = -y; z = -z;
    }
    void display() { cout << x << " " << y << " " << z; }
};
